import{_ as r,o,c as n,a2 as s}from"./chunks/framework.Dkj3JE0_.js";const p=JSON.parse('{"title":"日语基础语法","description":"","frontmatter":{"title":"日语基础语法"},"headers":[],"relativePath":"zh/blogs/JLPT-N2/grammars.md","filePath":"zh/blogs/JLPT-N2/grammars.md"}'),l={name:"zh/blogs/JLPT-N2/grammars.md"};function g(a,t,i,d,e,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="日语基础语法" tabindex="-1">日语基础语法 <a class="header-anchor" href="#日语基础语法" aria-label="Permalink to &quot;日语基础语法&quot;">​</a></h1><p>学习 N2 语法前，可以先复习这些基础句型。下文用 <strong>N</strong> 表示名词，<strong>A/B</strong> 表示句子中相应位置的词语。</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>规则：</strong> は读作 <em>wa</em>，标记话题，相当于“说到 A”。です使名词或な形容词作谓语的句子更礼貌。话题不一定等于语法上的主语。</p><ul><li>私は留学生です。——我是留学生。</li><li>あの方は先生です。——那位是老师。</li></ul><p><strong>否定：</strong> A は B ではありません；口语中也可说 B じゃありません。</p><ul><li>私は先生ではありません。——我不是老师。</li></ul><p><strong>疑问：</strong> 在礼貌句末加 か；书面语中问号可以省略。</p><ul><li>あの方は先生ですか。——那位是老师吗？</li></ul><p><strong>连接谓语：</strong> B で可连接名词或な形容词谓语与后面的谓语。这里的 で 是判断词的连接形式，不是表示动作地点的助词。</p><ul><li>田中さんは先生で、作家です。——田中既是老师，也是作家。</li></ul><h2 id="指示词" tabindex="-1">指示词 <a class="header-anchor" href="#指示词" aria-label="Permalink to &quot;指示词&quot;">​</a></h2><p><strong>规则：</strong> 词首的 <strong>こ</strong> 指靠近说话人，<strong>そ</strong> 指靠近听话人或前文提到的事物，<strong>あ</strong> 指离双方都远，<strong>ど</strong> 用于提问。在对话中，そ、あ 也能指双方熟悉或记忆中的事物；空间距离只是基本用法。</p><table tabindex="0"><thead><tr><th>位置</th><th>事物</th><th>地点</th><th>方向／礼貌地指人</th></tr></thead><tbody><tr><td>靠近说话人</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>靠近听话人</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>离双方都远</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>提问</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。——这是我的书。</li><li>駅はどちらですか。——车站在哪个方向？（礼貌说法）</li></ul><p>こちら／そちら／あちら／どちら根据语境也可礼貌地指人或选项。</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>规则：</strong> 这个句型说明 N1 这个地点有 N2。に标记地点，が标记存在的人或物。物品和植物用 <strong>あります</strong>；人和动物用 <strong>います</strong>。</p><ul><li>机の上に本があります。——桌上有一本书。</li><li>教室に学生がいます。——教室里有学生。</li></ul><p>表示拥有时，也可以把人作为存在的“地点”：私には兄がいます。——我有一个哥哥（字面上是“对我而言，有哥哥”）。</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>规则：</strong> には由地点助词 に 和话题／对比助词 は 组成。它把 N1 作为陈述范围，有时暗示与其他地点或人作对比。根据 N2 选择 あります／います。</p><ul><li>この町には大きな公園があります。——这座城市有一座大公园。</li><li>私のクラスには留学生がいます。——我们班有留学生。</li></ul><p>比较 <strong>教室に学生がいます</strong>（“教室里有学生”）与 <strong>教室には学生がいます</strong>（“教室里倒是有学生”）：后者更突出“教室”这个范围。</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>规则：</strong> 已经知道 N1，想说明它<strong>在哪里</strong>时，用这个语序。は标记已知话题，に标记所在地点。根据 N1 选择 あります／います。</p><ul><li>本は机の上にあります。——那本书在桌上。</li><li>先生は職員室にいます。——老师在办公室。</li></ul><p><strong>机の上に本があります</strong> 是引入“书”这一新信息；<strong>本は机の上にあります</strong> 是说明已知的书在哪里。</p><h2 id="过去时-名词谓语" tabindex="-1">过去时：名词谓语 <a class="header-anchor" href="#过去时-名词谓语" aria-label="Permalink to &quot;过去时：名词谓语&quot;">​</a></h2><p><strong>规则：</strong> 礼貌体的名词句把 です 改为 <strong>でした</strong>。否定过去时用 <strong>ではありませんでした</strong>，口语中也可说 <strong>じゃありませんでした</strong>。な形容词作谓语时也适用。</p><table tabindex="0"><thead><tr><th>含义</th><th>句型</th><th>例句</th></tr></thead><tbody><tr><td>过去肯定</td><td>A は B でした</td><td>昨日は休みでした。——昨天休息。</td></tr><tr><td>过去否定</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。——昨天不休息。</td></tr></tbody></table><p>普通体分别用 <strong>だった</strong> 和 <strong>ではなかった</strong>（或 <strong>じゃなかった</strong>）：昨日は休みだった。——昨天休息。</p><h2 id="过去时-动词谓语" tabindex="-1">过去时：动词谓语 <a class="header-anchor" href="#过去时-动词谓语" aria-label="Permalink to &quot;过去时：动词谓语&quot;">​</a></h2><p><strong>规则：</strong> 礼貌体动词肯定过去时由 <strong>～ます</strong> 变为 <strong>～ました</strong>；否定过去时由 <strong>～ません</strong> 变为 <strong>～ませんでした</strong>。普通体过去时取决于动词类别，不能简单地把 ます 换成 た。</p><table tabindex="0"><thead><tr><th>含义</th><th>礼貌体</th><th>普通体</th></tr></thead><tbody><tr><td>过去肯定</td><td>昨日、映画を見ました。——昨天看了电影。</td><td>昨日、映画を見た。</td></tr><tr><td>过去否定</td><td>昨日、映画を見ませんでした。——昨天没看电影。</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>例如，行きます → 行きました → 行った；食べます → 食べました → 食べた。</p><h2 id="疑问词与-が" tabindex="-1">疑问词与 が <a class="header-anchor" href="#疑问词与-が" aria-label="Permalink to &quot;疑问词与 が&quot;">​</a></h2><p><strong>规则：</strong> 询问“谁／什么是主语”时，疑问词后用 が，例如 誰が／何が。回答时通常也用 が 指明这个主语。如果把人或事物作为已知话题，或要作对比，也可能用 は；“用 が 提问就必须用 が 回答”过于绝对。</p><ul><li>誰が来ましたか。——谁来了？</li><li>田中さんが来ました。——田中来了。</li><li>何がありますか。——有什么？</li><li>机の上に本があります。——桌上有一本书。</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>规则：</strong> 这些词是 <strong>連体詞（连体词）</strong>，直接修饰名词，后面必须接名词：この本（这本书）、その本（你那边的／刚提到的那本书）、あの本（远处那本书）、どの本（哪本书）。不说出名词而单独指代事物时，改用 これ／それ／あれ／どれ。</p><ul><li>この本は面白いです。——这本书很有趣。</li><li>これは面白いです。——这个很有趣。</li><li>どの本があなたのですか。——哪本书是你的？</li><li>どれがあなたのですか。——哪个是你的？</li></ul><h2 id="n-を-n-をください" tabindex="-1">N を / N をください <a class="header-anchor" href="#n-を-n-をください" aria-label="Permalink to &quot;N を / N をください&quot;">​</a></h2><p><strong>规则：</strong> 助词 <strong>を</strong> 接在名词后，标记<strong>直接宾语</strong>。日语是 SOV 语言，动词通常在句末；宾语出现在前面，需要用 を 标记。</p><p><strong>N をください：</strong> ください 是 くださる（给）的命令形。<strong>N をください</strong> 意为“请给我……”，购物或点餐时很常用。</p><ul><li>水族館の入場券をください。——请给我一张水族馆门票。</li><li>チーズバーガーセットをください。——请给我一份芝士汉堡套餐。</li><li>ビールをください。——请给我一杯啤酒。</li></ul><p><strong>も：</strong> 表示“也”时用 <strong>も</strong>。も 和 を 不叠用——も <strong>替换</strong> を。</p><ul><li>それから、ホットコーヒーもください。——然后，也请给我一杯热咖啡。</li></ul><h2 id="n-を-数量-ください" tabindex="-1">N を（数量）ください <a class="header-anchor" href="#n-を-数量-ください" aria-label="Permalink to &quot;N を（数量）ください&quot;">​</a></h2><p><strong>规则：</strong> 要说明想要多少时，把<strong>数量词</strong>放在 ください 前：<strong>N を［数量词］ください</strong>。日语中数量词一般放在动词前。</p><ul><li>この水族館の入場券を3枚ください。——请给我三张这个水族馆的门票。／はい、3000円です。——好的，一共 3000 日元。</li><li>チーズバーガーセットを一つください。——请给我一份芝士汉堡套餐。</li><li>あのう、これを2本ください。——嗯，这个请给我两个。</li><li>シャツを3枚ください。——请给我三件衬衫。</li></ul><p>数量词也放在其他动词前：兄が2人います。——我有两个哥哥。／スマホが2台あります。——有两部智能手机。</p><p>这里用到的量词：<strong>枚</strong>（扁平的东西）、<strong>一つ</strong>（一般事物）、<strong>本</strong>（细长的东西）、<strong>人</strong>（人）、<strong>台</strong>（机器）。</p><h2 id="n-をお願いします-n-でお願いします" tabindex="-1">N をお願いします / N でお願いします <a class="header-anchor" href="#n-をお願いします-n-でお願いします" aria-label="Permalink to &quot;N をお願いします / N でお願いします&quot;">​</a></h2><p><strong>规则：</strong> <strong>お願いします</strong> 是礼貌的请求（“拜托了”）。在很多点餐场合可以替换 <strong>ください</strong>。</p><ul><li>ホットコーヒーをお願いします。——请来一杯热咖啡。</li><li>これを４つお願いします。——这个请来四个。</li></ul><p><strong>N でお願いします：</strong> 助词 <strong>で</strong> 表示<strong>手段／方式／所选的选项</strong>。用于指定尺寸、付款方式、联系渠道等——尤其是物品本身在语境中已经清楚的时候。</p><ul><li>Sサイズでお願いします。——请要小杯。（店员已经问了尺寸时很自然）</li><li>Sサイズのコーヒーをお願いします。——请来一杯小杯咖啡。（说出了物品）</li><li>アリペイでお願いします。——用支付宝付。（付款时）</li><li>Eメールでお願いします。——请用电子邮件联系。（被问到联系方式时）</li></ul><h2 id="n-でございます" tabindex="-1">N でございます <a class="header-anchor" href="#n-でございます" aria-label="Permalink to &quot;N でございます&quot;">​</a></h2><p><strong>规则：</strong> <strong>でございます</strong> 是比 <strong>です</strong> 更礼貌、更正式的说法（丁寧語）。常用于服务用语、演讲及其他正式场合。一般用于说话人自己、自己一方的人或属于他们的事物——通常不用于需要尊敬的听话人或听话人的事物。</p><ul><li>エレベーターはこちらでございます。——电梯在这边。</li><li>私が担当者でございます。——我是负责人。</li><li>部長の田中でございます。——这位是田中部长。<em>（同事向客户介绍自己公司的部长）</em></li></ul><p>对话：</p><ul><li>A <em>（外部人员）</em>：田中部長は、今日、お休みですか。——田中部长今天休息吗？</li><li>B <em>（同事）</em>：はい、休みでございます。——是的，他今天休息。</li></ul><h2 id="どうなさいますか-はどうですか" tabindex="-1">どうなさいますか / ～はどうですか <a class="header-anchor" href="#どうなさいますか-はどうですか" aria-label="Permalink to &quot;どうなさいますか / ～はどうですか&quot;">​</a></h2><p><strong>规则：</strong> <strong>どう</strong> 意为“怎样／（选择）什么”。<strong>なさいます</strong> 是 <strong>する</strong> 的尊敬语，所以 <strong>どうなさいますか</strong> 是非常礼貌的“您要什么？／您想怎么做？”——服务用语中很常见。</p><ul><li>A：ホットコーヒーのサイズはどうなさいますか。——热咖啡您要什么尺寸？</li><li>B：Lサイズでお願いします。——请要大杯。</li></ul><p><strong>～はどうですか：</strong> <strong>どう</strong> 与 <strong>ですか</strong> 一起作谓语时，<strong>～はどうですか</strong> 用来询问意见或情况。</p><ul><li>このコーヒーはどうですか。——这杯咖啡怎么样？</li><li>清華大学はどうですか。——清华大学怎么样？</li><li>最近はどうですか。——最近怎么样？</li></ul><h2 id="形容词谓语-礼貌非过去" tabindex="-1">形容词谓语（礼貌非过去） <a class="header-anchor" href="#形容词谓语-礼貌非过去" aria-label="Permalink to &quot;形容词谓语（礼貌非过去）&quot;">​</a></h2><p><strong>规则：</strong> 形容词谓语描述<strong>状态</strong>或<strong>恒常的性质</strong>。日语形容词分两类：<strong>I 类</strong>（い形容词，以 <strong>い</strong> 结尾）和 <strong>II 类</strong>（な形容词／形容动词）。</p><p><strong>礼貌非过去（敬体）：</strong></p><ol><li><strong>肯定：</strong> I 类 → <strong>A₁ + です</strong>；II 类 → <strong>A₂ + です</strong>。</li><li><strong>否定：</strong> I 类 → 去掉 <strong>い</strong>，变为 <strong>く + ありません</strong>；II 类 → <strong>A₂ + ではありません</strong>（口语：<strong>じゃありません</strong>）。</li></ol><table tabindex="0"><thead><tr><th>类别</th><th>时态</th><th>肯定（礼貌）</th><th>否定（礼貌）</th></tr></thead><tbody><tr><td>I 类（如 高い）</td><td>非过去</td><td>高いです</td><td>高くありません</td></tr><tr><td>II 类（如 静か）</td><td>非过去</td><td>静かです</td><td>静かではありません（じゃありません）</td></tr></tbody></table><p>口语中 <strong>では</strong> 可换成 <strong>じゃ</strong>。</p><ul><li>東京は寒いです。——东京很冷。</li><li>あの映画は面白くありません。——那部电影不好看。</li><li>先生は親切です。——老师很亲切。</li><li>日本語は簡単ではありません。——日语不简单。</li></ul><p><strong>いい：</strong> 从旧形式 <strong>よい</strong> 变形。いいです 的否定是 <strong>よくありません</strong>。</p><ul><li>成績はよくありません。——成绩不好。</li></ul><h2 id="n1-は-n2-が-〜" tabindex="-1">N₁ は N₂ が 〜 <a class="header-anchor" href="#n1-は-n2-が-〜" aria-label="Permalink to &quot;N₁ は N₂ が 〜&quot;">​</a></h2><p><strong>规则：</strong> <strong>は</strong> 标记<strong>话题</strong>（句子在谈论什么）；<strong>が</strong> 标记后面谓语的<strong>主语</strong>。在 <strong>A は B が X です</strong> 中，A 通常是人或整体，B 是 A 的部分或方面，<strong>B が X です</strong> 描述 A 的性质。这种“话题 + 部分／方面”的句型在日语中很常见，与汉语或英语的表达方式常常不同。</p><ul><li>象は鼻が長いです。——大象鼻子长。</li><li>富士山は形がいいです。——富士山形状很美。</li><li>今日は天気がいいです。——今天天气很好。</li><li>彼女は性格が明るいです。——她性格开朗。</li></ul><h2 id="あまり-そんなに-形容词-否定" tabindex="-1">あまり / そんなに + 形容词（否定） <a class="header-anchor" href="#あまり-そんなに-形容词-否定" aria-label="Permalink to &quot;あまり / そんなに + 形容词（否定）&quot;">​</a></h2><p><strong>规则：</strong> 程度副词 <strong>あまり</strong> 和 <strong>そんなに</strong> 与形容词<strong>否定</strong>形连用，意为“不太……”／“没那么……”。与 I 类和 II 类形容词的礼貌否定形一起使用（如 寒くありません、難しくありません）。</p><ul><li>A：東京は寒いですか。——东京冷吗？</li><li>B：いいえ、あまり寒くありません。——不，不太冷。</li><li>日本語はそんなに難しくありません。——日语没那么难。</li><li>このパソコンはそんなに遅くありません。——这台电脑没那么慢。</li></ul><h2 id="〜から-原因" tabindex="-1">〜から（原因） <a class="header-anchor" href="#〜から-原因" aria-label="Permalink to &quot;〜から（原因）&quot;">​</a></h2><p><strong>规则：</strong> 句末或分句末的 <strong>から</strong> 表示<strong>原因／理由</strong>（“因为……”）。可以单独作为回答，也可以跟在先给出结论的句子后面。</p><ul><li>（中村さんは）とても真面目ですから。——因为（中村）非常认真。</li><li>アイスクリームがいいです。暑いですから。——冰淇淋好。因为天热。</li><li>A：寒いですね。——好冷啊。</li><li>B：そうですね。今日は雪ですから。——是啊。因为今天下雪。</li></ul><h2 id="n-はどうですか-询问性质-意见" tabindex="-1">N はどうですか（询问性质／意见） <a class="header-anchor" href="#n-はどうですか-询问性质-意见" aria-label="Permalink to &quot;N はどうですか（询问性质／意见）&quot;">​</a></h2><p><strong>规则：</strong> <strong>どう</strong> 意为“怎样／什么样”。<strong>N はどうですか</strong> 询问某事物的<strong>性质</strong>或听话人对它的<strong>看法</strong>。用形容词谓语（或简短的评价）回答。</p><ul><li>A：日本の留学生生活はどうですか。——在日本的留学生活怎么样？</li><li>B：順調ですよ。——很顺利哦。</li><li>A：日本語はどうですか。——日语怎么样？</li><li>B：難しいです。——很难。</li><li>A：この映画はどうですか。——这部电影怎么样？</li><li>B：とても面白いです。——非常有意思。</li></ul><h2 id="〜よ-断定-强调" tabindex="-1">〜よ（断定／强调） <a class="header-anchor" href="#〜よ-断定-强调" aria-label="Permalink to &quot;〜よ（断定／强调）&quot;">​</a></h2><p><strong>规则：</strong> 句末的 <strong>よ</strong> 表示说话人的<strong>断定</strong>、强烈主张或强调语气——常用于向听话人传达新信息或明确提醒。</p><ul><li>中村さんのおかげですよ。——都是托中村的福哦。</li><li>山羊座の人はみんな真面目ですよ。——摩羯座的人都很认真哦。</li><li>日本語はそんなに難しくありませんよ。——日语没那么难哦。</li></ul><h2 id="〜ね-轻微感叹" tabindex="-1">〜ね（轻微感叹） <a class="header-anchor" href="#〜ね-轻微感叹" aria-label="Permalink to &quot;〜ね（轻微感叹）&quot;">​</a></h2><p><strong>规则：</strong> 句末的 <strong>ね</strong> 可以表示<strong>轻微的感叹／共同的感受</strong>。读<strong>降调</strong>（↘）。想更柔和时，可以拉长为 <strong>ねえ</strong>。</p><ul><li>由加ちゃんはすごいですね。↘——由加真厉害啊。</li><li>この洋服、かわいいですね。↘——这件衣服真可爱啊。</li><li>由加ちゃんのこのスマホケース、かわいいですね。↘——由加，你这个手机壳真可爱啊。</li></ul><h2 id="形容词谓语-礼貌过去" tabindex="-1">形容词谓语（礼貌过去） <a class="header-anchor" href="#形容词谓语-礼貌过去" aria-label="Permalink to &quot;形容词谓语（礼貌过去）&quot;">​</a></h2><p><strong>规则：</strong> 形容词谓语的过去形因类别而异。</p><ol><li><strong>过去肯定：</strong> I 类 → 去掉 <strong>い</strong>，变为 <strong>かったです</strong>；II 类 → <strong>A₂ + でした</strong>。</li><li><strong>过去否定：</strong> I 类 → 去掉 <strong>い</strong>，变为 <strong>く + ありませんでした</strong>；II 类 → <strong>A₂ + ではありませんでした</strong>（口语：<strong>じゃありませんでした</strong>）。</li></ol><table tabindex="0"><thead><tr><th>类别</th><th>时态</th><th>肯定（礼貌）</th><th>否定（礼貌）</th></tr></thead><tbody><tr><td>I 类（如 高い）</td><td>非过去</td><td>高いです</td><td>高くありません</td></tr><tr><td></td><td>过去</td><td>高かったです</td><td>高くありませんでした</td></tr><tr><td>II 类（如 静か）</td><td>非过去</td><td>静かです</td><td>静かではありません（じゃありません）</td></tr><tr><td></td><td>过去</td><td>静かでした</td><td>静かではありませんでした（じゃありませんでした）</td></tr></tbody></table><p>口语中 <strong>では</strong> 可换成 <strong>じゃ</strong>。</p><ul><li>A：お客さんは多かったですか。——客人多吗？</li><li>B：ううん、平日の昼間ですから、ばらばらでしたよ。——不多，因为是工作日的白天，稀稀拉拉的。</li><li>子供の時、生活は豊かではありませんでした。——小时候生活不富裕。</li><li>10年前の家賃はそんなに高くありませんでした。——十年前的房租没那么贵。</li></ul><h2 id="ない-否定-形容词与名词的四象限" tabindex="-1">ない（否定）／形容词与名词的四象限 <a class="header-anchor" href="#ない-否定-形容词与名词的四象限" aria-label="Permalink to &quot;ない（否定）／形容词与名词的四象限&quot;">​</a></h2><p><strong>规则：</strong> <strong>ない</strong> 意为“不／不存在”。它本身是 <strong>I 类</strong>形容词，也作为<strong>辅助形容词</strong>接在其他形容词后（以及名词／II 类句型中）表示否定。</p><p>在 <strong>ない</strong> 后加 <strong>です</strong> 更礼貌，与 <strong>ありません</strong> 形式相对应：</p><ul><li>非过去：<strong>ありません</strong> ＝ <strong>ないです</strong></li><li>过去：<strong>ありませんでした</strong> ＝ <strong>なかったです</strong></li></ul><p>时态（非过去／过去）× 肯否（肯定／否定）合起来构成<strong>形容词／名词的四象限</strong>。</p><h3 id="形容词四象限-礼貌" tabindex="-1">形容词四象限（礼貌） <a class="header-anchor" href="#形容词四象限-礼貌" aria-label="Permalink to &quot;形容词四象限（礼貌）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>时态</th><th>肯定</th><th>否定</th></tr></thead><tbody><tr><td>I 类（如 高い）</td><td>非过去</td><td>高いです</td><td>高くありません ／ 高くないです</td></tr><tr><td></td><td>过去</td><td>高かったです</td><td>高くありませんでした ／ 高くなかったです</td></tr><tr><td>II 类（如 静か）</td><td>非过去</td><td>静かです</td><td>静かではありません（じゃありません） ／ 静かではないです（じゃないです）</td></tr><tr><td></td><td>过去</td><td>静かでした</td><td>静かではありませんでした（じゃありませんでした） ／ 静かではなかったです（じゃなかったです）</td></tr></tbody></table><h3 id="名词四象限-礼貌" tabindex="-1">名词四象限（礼貌） <a class="header-anchor" href="#名词四象限-礼貌" aria-label="Permalink to &quot;名词四象限（礼貌）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>时态</th><th>肯定</th><th>否定</th></tr></thead><tbody><tr><td>名词（如 学生）</td><td>非过去</td><td>学生です</td><td>学生ではありません（じゃありません） ／ 学生ではないです（じゃないです）</td></tr><tr><td></td><td>过去</td><td>学生でした</td><td>学生ではありませんでした（じゃありませんでした） ／ 学生ではなかったです（じゃなかったです）</td></tr></tbody></table><p>口语中 <strong>では</strong> 可换成 <strong>じゃ</strong>。</p><h2 id="形容词的连接" tabindex="-1">形容词的连接 <a class="header-anchor" href="#形容词的连接" aria-label="Permalink to &quot;形容词的连接&quot;">​</a></h2><p><strong>规则：</strong> 要把形容词并列或依次连接，用<strong>前一个</strong>形容词的<strong>连用形</strong>（中顿）。形式只取决于前一个形容词，与后面接什么无关。时态由<strong>最后的</strong>谓语表示；中间的形式不表示时态。</p><ul><li><p><strong>I 类：</strong> 去掉 <strong>い</strong> → <strong>くて</strong>（A₁ い → く + て）</p></li><li><p><strong>II 类：</strong> <strong>A₂ + で</strong></p></li><li><p>映画の主人公は背が高くて、魅力的です。——电影的主人公个子高，又有魅力。<em>（高くて = I 类；魅力的 = II 类）</em></p></li><li><p>昨日の試験問題は複雑で、難しかったです。——昨天的考题又复杂又难。<em>（複雑で = II 类；过去时在 難しい 上）</em></p></li><li><p>映画の主人公は背が高くて、かっこいいです。——……个子高，又帅。<em>（I 类 + I 类——仍是 高くて）</em></p></li><li><p>映画の主人公は背が高くて、魅力的です。——……个子高，又有魅力。<em>（I 类 + II 类——仍是 高くて）</em></p></li><li><p>昨日の映画の主人公は背が高くて、魅力的でした。——昨天那部电影的主人公个子高，又有魅力。<em>（中间仍是 高くて；过去时只在 でした 上）</em></p></li></ul><h2 id="n-まで-终点" tabindex="-1">N まで（终点） <a class="header-anchor" href="#n-まで-终点" aria-label="Permalink to &quot;N まで（终点）&quot;">​</a></h2><p><strong>规则：</strong> <strong>まで</strong> 接在名词后，表示<strong>终点／界限</strong>（“到……为止”）。可用于<strong>时间</strong>名词（本课），也可用于<strong>地点</strong>名词表示空间上的终点。<strong>N まで</strong> 也可以接 <strong>です</strong> 构成名词谓语句。</p><ul><li>わたしは昨日、遅くまで日本語の試験でした。——我昨天日语考试一直考到很晚。</li><li>今日の授業はここまでです。——今天的课就到这里。</li><li>あの歌手のライブツアーは来月20日までです。——那位歌手的巡回演唱会到下个月 20 号为止。</li></ul><h2 id="全然-形容词-否定" tabindex="-1">全然 + 形容词（否定） <a class="header-anchor" href="#全然-形容词-否定" aria-label="Permalink to &quot;全然 + 形容词（否定）&quot;">​</a></h2><p><strong>规则：</strong> 与 <strong>あまり</strong> 一样，<strong>全然</strong> 是程度副词，与形容词<strong>否定</strong>形连用：“完全不……”。口语中，<strong>全然</strong> 可以单独回答“一点也不”。</p><ul><li>A：昨日の試験は難しかったですか。——昨天的考试难吗？</li><li>B：全然難しくなかったですよ。——一点也不难哦。</li><li>わたしは運動が全然好きではありません。——我一点也不喜欢运动。</li><li>彼女の料理は全然美味しくありません。——她做的菜一点也不好吃。</li><li>A：日本語の試験は難しかったですか。——日语考试难吗？</li><li>B：ううん、全然。——不，一点也不。</li></ul><h2 id="n-とか-列举例子" tabindex="-1">N とか（列举例子） <a class="header-anchor" href="#n-とか-列举例子" aria-label="Permalink to &quot;N とか（列举例子）&quot;">​</a></h2><p><strong>规则：</strong> <strong>とか</strong> 接在名词后，用来<strong>列举例子</strong>（……之类的）。口语中常用，可以出现一次或多次。用 <strong>とか</strong> 时，话题／主语／宾语助词 <strong>は / が / を</strong> 可以省略。</p><ul><li>A：どんな飲み物が好きですか。——你喜欢什么样的饮料？</li><li>B：ミルクティーとか、コーラとか。——奶茶啦，可乐之类的。</li><li>木曜日の午後以降とかはどうですか。——周四下午以后之类的时间怎么样？</li></ul><h2 id="形容词修饰名词-连体形" tabindex="-1">形容词修饰名词（连体形） <a class="header-anchor" href="#形容词修饰名词-连体形" aria-label="Permalink to &quot;形容词修饰名词（连体形）&quot;">​</a></h2><p><strong>规则：</strong> 形容词除了作谓语，还可以放在<strong>名词前</strong>修饰名词。这种形式叫<strong>连体形</strong>。</p><ul><li><p><strong>I 类</strong>（い形容词）：<strong>A₁ + 名词</strong>——形容词<strong>直接</strong>接名词（保留 <strong>い</strong> 词尾）。</p></li><li><p><strong>II 类</strong>（な形容词）：<strong>A₂ + な + 名词</strong>——在名词前插入 <strong>な</strong>。因此有些书称之为 <strong>な形容词</strong>。</p></li><li><p>白いパソコン——白色的电脑 <em>（I 类：白い + パソコン）</em></p></li><li><p>きれいな町——干净／美丽的城市 <em>（II 类：きれい + な + 町）</em></p></li></ul><h2 id="n-が-主语-——作为主语标记的-は-与-が" tabindex="-1">N が（主语）——作为主语标记的 は 与 が <a class="header-anchor" href="#n-が-主语-——作为主语标记的-は-与-が" aria-label="Permalink to &quot;N が（主语）——作为主语标记的 は 与 が&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>长期容易混淆：<strong>は</strong> 和 <strong>が</strong> 都能标记看起来像“主语”的成分，但它们回答的信息问题不同。<strong>が</strong> = 主语对听话人来说是<strong>新的／未知的</strong>（焦点在 <strong>が</strong> 前面的名词上）。<strong>は</strong> = 主语是<strong>已知的</strong>（旧信息）；焦点落在 <strong>は</strong> <strong>后面</strong>的内容上。</p></div><p><strong>规则：</strong> 引出或指认听话人尚未掌握的事物时，用 <strong>が</strong>。一旦该事物在对话中已经确定，就改用 <strong>は</strong>。询问主语的疑问词问句（<strong>だれが</strong>、<strong>何が</strong>……）用 <strong>が</strong>；回答通常在被指认的事物上保留 <strong>が</strong>，之后再谈论这个人／事物的句子则用 <strong>は</strong>。</p><ul><li>ほら、あそこの男の人。あの人<strong>は</strong>中村さんのお兄さんですよ。——你看，那边那个男的。他是中村的哥哥哦。<em>（あの人 已被指出 → <strong>は</strong>；焦点在他是谁。）</em></li><li>A：へえ、小学校の時の記念写真ですか。中村さんは、これ？——哇，小学时的纪念照？中村，这是你吗？</li><li>B：違いますよ。これ<strong>が</strong>わたしです。——不是哦。<strong>这个</strong>才是我。<em>（指认是哪一个 → <strong>が</strong>；焦点在 これ。）</em></li><li>こちらのパソコン<strong>が</strong>、今お得ですよ。——<strong>这台</strong>电脑现在很划算哦。<em>（把这台挑出来作为新焦点 → <strong>が</strong>。）</em></li><li>A：日本語<strong>は</strong>難しいですか。——日语难吗？<em>（话题 = 日语 → <strong>は</strong>。）</em></li><li>B：ええ、文法<strong>が</strong>難しいです。——是的，难的是<strong>语法</strong>。<em>（指明难的部分作为新焦点 → <strong>が</strong>。）</em></li><li>A：だれ<strong>が</strong>留学生ですか。——<strong>谁</strong>是留学生？<em>（だれが——总是用 <strong>が</strong>。）</em></li><li>B：あの人<strong>が</strong>留学生で、ジョージさんです。ジョージさん<strong>は</strong>今、先生の研究室にいます。——<strong>那个人</strong>是留学生，叫乔治。乔治现在在老师的研究室。<em>（用 <strong>が</strong> 指认，之后已知的乔治 → <strong>は</strong>。）</em></li></ul><h2 id="n-と同じ-与-n-相同" tabindex="-1">N と同じ（与 N 相同） <a class="header-anchor" href="#n-と同じ-与-n-相同" aria-label="Permalink to &quot;N と同じ（与 N 相同）&quot;">​</a></h2><p><strong>规则：</strong> <strong>同じ</strong> 是 <strong>II 类</strong>形容词，意为“相同／一样”。在比较对象的名词后加 <strong>と</strong>：<strong>N と同じ</strong> =“与 N 相同”。</p><p><strong>例外（容易出错）：</strong> <strong>同じ</strong> 作连体修饰名词时，<strong>不</strong>加 <strong>な</strong>——直接写 <strong>同じ + 名词</strong>（不说 <em>同じな</em>）。</p><ul><li>白いパソコンと同じ大きさです。——和白色的电脑一样大。</li><li>李さんは中村さんと同じ大学です。——小李和中村在同一所大学。</li><li>経済学部は法学部と同じ建物です。——经济学院和法学院在同一栋楼。</li></ul><h2 id="n-がほしいです-想要-n" tabindex="-1">N がほしいです（想要 N） <a class="header-anchor" href="#n-がほしいです-想要-n" aria-label="Permalink to &quot;N がほしいです（想要 N）&quot;">​</a></h2><p><strong>规则：</strong> <strong>ほしい</strong> 是 <strong>I 类</strong>形容词，意为“想要（得到某物）”。按其他 I 类形容词的方式变形。想要的东西通常用 <strong>が</strong> 标记：<strong>N がほしいです</strong> ≈“我想要 N”。</p><p><strong>人称限制：</strong> <strong>ほしい</strong> 主要用于<strong>说话人</strong>自己的愿望（第一人称）。避免用于第三人称的愿望；问听话人时，基本只在关系亲近的家人／朋友之间可以用。</p><p><strong>ほしい</strong> 也可以作连体修饰名词（<strong>ほしい + 名词</strong>）。</p><ul><li>（私は）新しいスーツケースがほしいです。——我想要一个新的行李箱。</li><li>地下鉄がなかった時は、車がほしかったです。——没有地铁的时候，我想要一辆车。</li><li>A：ほしいものはありますか。——有想要的东西吗？</li><li>B：ありますよ。お金がほしいです。——有啊。我想要钱。</li></ul><h2 id="分句1-が、分句2-转折-缓和语气" tabindex="-1">分句₁ が、分句₂（转折／缓和语气） <a class="header-anchor" href="#分句1-が、分句2-转折-缓和语气" aria-label="Permalink to &quot;分句₁ が、分句₂（转折／缓和语气）&quot;">​</a></h2><p><strong>规则：</strong> 句中的 <strong>が</strong> 可以连接两个分句，表示<strong>对比／转折</strong>（“……，但是……”／“虽然分句₁，但分句₂”）。在 <strong>すみませんが</strong>／<strong>失礼ですが</strong> 这类固定说法后，它起缓和语气的作用——转折意味很弱，常常不必译成“但是”。分句₂ 也可以<strong>省略</strong>，句末留下 <strong>が</strong>，使请求或愿望显得委婉。</p><ul><li>歴史の授業は難しいですが、面白いです。——历史课虽然难，但很有意思。</li><li>失礼ですが、お名前は？——不好意思，请问您贵姓？</li><li>新しいパソコンがほしいのですが。——我想要一台新电脑……<em>（分句₂ 留白／委婉的请求。）</em></li></ul><h2 id="n1-も-n2-も-n1-和-n2-都" tabindex="-1">N₁ も N₂ も（N₁ 和 N₂ 都……） <a class="header-anchor" href="#n1-も-n2-も-n1-和-n2-都" aria-label="Permalink to &quot;N₁ も N₂ も（N₁ 和 N₂ 都……）&quot;">​</a></h2><p><strong>规则：</strong> 在两个并列的名词后各加 <strong>も</strong>：<strong>N₁ も N₂ も ～</strong>。表示两者共有同一个谓语——“N₁ 和 N₂ 都……”。</p><ul><li>兄も姉も会社員です。——我哥哥和姐姐都是公司职员。</li><li>日本料理も中華料理も美味しいです。——日本菜和中国菜都好吃。</li><li>メモリーもストレージも大きいです。——内存和存储空间都很大。</li></ul><h2 id="比较句型-比較" tabindex="-1">比较句型（比較） <a class="header-anchor" href="#比较句型-比較" aria-label="Permalink to &quot;比较句型（比較）&quot;">​</a></h2><p>日语有几种比较两个名词的固定句型。下面四种是本课的核心。</p><h3 id="_1-n1-は-n2-より" tabindex="-1">(1) N₁ は N₂ より ～ <a class="header-anchor" href="#_1-n1-は-n2-より" aria-label="Permalink to &quot;(1) N₁ は N₂ より ～&quot;">​</a></h3><p><strong>规则：</strong> <strong>より</strong> 表示比较的<strong>基准</strong>。<strong>N₁ は N₂ より ～</strong> 意为 N₁ 在谓语所说的性质上比 N₂ 更甚（“N₁ 比 N₂ 更……”）。差距大时加 <strong>ずっと</strong>（“……得多”）。</p><ul><li>中国は日本より広いです。——中国比日本大。</li><li>（こちらのパソコンは）さっきのよりメモリーがずっと大きいですよ。——（这台电脑的）内存比刚才那台大得多哦。</li><li>スマホはパソコンより値段が高いです。——智能手机比电脑贵。</li></ul><h3 id="_2-n2-より-n1-のほうが" tabindex="-1">(2) N₂ より N₁ のほうが ～ <a class="header-anchor" href="#_2-n2-より-n1-のほうが" aria-label="Permalink to &quot;(2) N₂ より N₁ のほうが ～&quot;">​</a></h3><p><strong>规则：</strong> 同样的比较，换一种说法：<strong>N₂ より N₁ のほうが ～</strong> =“与 N₂ 相比，N₁ 更……”。<strong>ほう</strong>（方）意为“一方／两者之一”。常用来<strong>回答</strong>句型 (4)；回答时 <strong>N₂ より</strong> 常被省略 → <strong>N₁ のほうが ～</strong>。</p><ul><li>日本より中国のほうが広いです。——与日本相比，中国更大。</li><li>パソコンよりスマホのほうが値段が高いです。——与电脑相比，智能手机更贵。</li></ul><h3 id="_3-n2-は-n1-ほど-否定" tabindex="-1">(3) N₂ は N₁ ほど ～（否定） <a class="header-anchor" href="#_3-n2-は-n1-ほど-否定" aria-label="Permalink to &quot;(3) N₂ は N₁ ほど ～（否定）&quot;">​</a></h3><p><strong>规则：</strong> 名词后的 <strong>ほど</strong> 表示<strong>程度</strong>。与<strong>否定</strong>谓语连用，<strong>N₂ は N₁ ほど ～ない</strong> 意为 N₂ <strong>达不到</strong> N₁ 的程度——“N₂ 不如 N₁ 那么……”。</p><ul><li>日本は中国ほど広くありません。——日本没有中国那么大。</li><li>パソコンはスマホほど値段が高くありません。——电脑没有智能手机那么贵。</li></ul><h3 id="_4-n1-と-n2-とどちら-のほう-が-か" tabindex="-1">(4) N₁ と N₂ とどちら（のほう）が ～か <a class="header-anchor" href="#_4-n1-と-n2-とどちら-のほう-が-か" aria-label="Permalink to &quot;(4) N₁ と N₂ とどちら（のほう）が ～か&quot;">​</a></h3><p><strong>规则：</strong> 问两者中哪一个更……：<strong>N₁ と N₂ とどちら（のほう）が ～か</strong>。用句型 (2) 回答，通常只说 <strong>N のほうが ～</strong>。</p><ul><li>A：中国と日本とどちら（のほう）が広いですか。——中国和日本，哪个更大？</li><li>B：中国のほうが広いです。——中国更大。</li><li>A：パソコンとスマホとどちらが高いですか。——电脑和智能手机，哪个更贵？</li><li>B：スマホのほうが高いです。——智能手机更贵。</li></ul><h2 id="n-なので、-原因与理由-ii" tabindex="-1">N なので、～（原因与理由 II） <a class="header-anchor" href="#n-なので、-原因与理由-ii" aria-label="Permalink to &quot;N なので、～（原因与理由 II）&quot;">​</a></h2><p><strong>规则：</strong> <strong>ので</strong> 连接两个分句，表示原因及其结果。名词谓语用 <strong>N + な + ので</strong>，意为“因为（是）N，……”（见第 5 课语法 1）。与 <strong>から</strong>（第 9 课语法 4）相比，<strong>ので</strong> 强调客观原因，语气更柔和、更正式。</p><ul><li>僕は神奈川県の湘南の出身なので、僕も『スラムダンク』が大好きですよ。——因为我是神奈川县湘南出身，所以我也特别喜欢《灌篮高手》哦。</li><li>雨なので、運動会は中止です。——因为下雨，运动会取消了。</li><li>学生なので、お金がないです。——因为是学生，所以没钱。</li></ul><h2 id="n-が-对象标记-が-iii" tabindex="-1">N が～（对象标记 が III） <a class="header-anchor" href="#n-が-对象标记-が-iii" aria-label="Permalink to &quot;N が～（对象标记 が III）&quot;">​</a></h2><p><strong>规则：</strong> 助词 <strong>が</strong> 除了标记主语，还可以标记对象。本课中，<strong>が</strong> 标记能力或技能水平的对象。这类表达主要是 <strong>II 类（な）形容词</strong>和<strong>动词</strong>。</p><ul><li><p><strong>II 类（な）形容词：</strong> N が 上手／下手（擅长／不擅长）、好き／嫌い（喜欢／讨厌）、得意／苦手（拿手／不拿手）です。</p></li><li><p><strong>动词：</strong> N が できます（会）、わかります（懂）。</p></li><li><p>私は運動が嫌いです。——我讨厌运动。</p></li><li><p>辛いものが苦手です。——我吃不了辣的。</p></li><li><p>兄は歴史が得意です。——我哥哥历史很拿手。</p></li><li><p>先生の話がよくわかりません。——我不太懂老师讲的。</p></li><li><p>父は料理ができます。——我父亲会做饭。</p></li></ul><h2 id="n1の中で-n2がいちばん-最高级-で-表示范围" tabindex="-1">（N₁の中で）N₂がいちばん～（最高级；で 表示范围） <a class="header-anchor" href="#n1の中で-n2がいちばん-最高级-で-表示范围" aria-label="Permalink to &quot;（N₁の中で）N₂がいちばん～（最高级；で 表示范围）&quot;">​</a></h2><p><strong>规则：</strong> 在比较句型的基础上，这是<strong>最高级</strong>：在 <strong>N₁</strong> 给出的范围内，<strong>N₂</strong> 最具有谓语所描述的性质。名词后的助词 <strong>で</strong> 限定范围，副词 <strong>いちばん</strong> 意为“最”。最高级用于在三个或以上的人或事物中挑出最突出的一个。译为“（在 N₁ 中，）N₂ 最……”。</p><ul><li>日本の漫画の中で、『スラムダンク』がいちばん好きです。——日本漫画中，我最喜欢《灌篮高手》。</li><li>スポーツの中でバスケットボールがいちばん好きです。——体育运动中，我最喜欢篮球。</li><li>クラスの中で、李さんがいちばん頭がいいです。——班上小李最聪明。</li><li>日本料理の中で、お寿司がいちばん好きです。——日本菜中，我最喜欢寿司。</li></ul><h2 id="は-が、-は-。-对比的-は-ii" tabindex="-1">～は～が、～は～。（对比的 は II） <a class="header-anchor" href="#は-が、-は-。-对比的-は-ii" aria-label="Permalink to &quot;～は～が、～は～。（对比的 は II）&quot;">​</a></h2><p><strong>规则：</strong> 在用 <strong>が</strong>（“但是”）连接的转折句中，当两个分句结构相似、彼此对比时，两个话题都用 <strong>は</strong> 标记。<strong>は … は</strong> 这一对承担对比的意思。</p><ul><li>バスケットボールはできませんが、サッカーとテニスはすこしできます。——篮球我不会，但足球和网球会一点。</li><li>日本語は上手ですが、英語は下手です。——日语很好，但英语很差。</li><li>昨日は寒かったですが、今日はとても暑いです。——昨天很冷，但今天非常热。</li><li>私は学生ですが、妹は会社員です。——我是学生，但妹妹是公司职员。</li></ul><h2 id="n-に-状态或性质的对象" tabindex="-1">N に～（状态或性质的对象） <a class="header-anchor" href="#n-に-状态或性质的对象" aria-label="Permalink to &quot;N に～（状态或性质的对象）&quot;">​</a></h2><p><strong>规则：</strong> 名词后的助词 <strong>に</strong> 表示后面的能力、态度或性质所针对的对象，相当于“对于／在……方面”。谓语通常是表示<strong>性质</strong>、<strong>状态</strong>或<strong>能力</strong>的形容词，如 必要、便利、詳しい。</p><ul><li>マスクは外出に必要です。——外出需要口罩。</li><li>横の中国語訳は日本語学習に便利です。——旁边的中文翻译对学日语很方便。</li><li>兄は中国の歴史にも、日本の歴史にも詳しいです。——我哥哥对中国历史和日本历史都很精通。</li><li>駅の近くのアパートは、買い物に便利です。——车站附近的公寓买东西很方便。</li></ul><h2 id="の-ん-です-说明-i-形容词和名词" tabindex="-1">～の（／ん）です（说明 I：形容词和名词） <a class="header-anchor" href="#の-ん-です-说明-i-形容词和名词" aria-label="Permalink to &quot;～の（／ん）です（说明 I：形容词和名词）&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>本课最重要的句型。<strong>～の（／ん）です</strong> 把普通的陈述变成<strong>说明</strong>：把事实作为情况背后的原因、背景或“其实是……”提出来。口语中通常缩略为 <strong>～んです</strong>。汉语和英语没有直接对应的说法，所以通常不译出来。</p></div><p><strong>接续：</strong></p><ul><li>N + な + の（／ん）です</li><li>Aɪ（い形容词）+ の（／ん）です</li><li>Aɪɪ（な形容词）+ な + の（／ん）です</li></ul><p><strong>规则：</strong> 这个句型在会话中非常常用。它接在<strong>形容词的连体形</strong>或 <strong>N + な</strong> 后，口语中多用 <strong>～んです</strong>。用来陈述说话人自己的看法，或解释、说明情况。主要有三种用法。</p><h3 id="_1-说明情况或给出理由" tabindex="-1">(1) 说明情况或给出理由 <a class="header-anchor" href="#_1-说明情况或给出理由" aria-label="Permalink to &quot;(1) 说明情况或给出理由&quot;">​</a></h3><p>给出前面已提到的事情背后的<strong>理由或原因</strong>，多用于说明说话人自己的情况。</p><ul><li>実は『キャプテン翼』も『テニスの王子様』も好きなんですよ。——其实《足球小将》和《网球王子》我也喜欢哦。</li><li>すみません、今はちょっと忙しいんです。——对不起，我现在有点忙。</li><li>私は冷たい飲み物が苦手なんです。——我不太喜欢冷饮。</li></ul><h3 id="_2-认同与恍然大悟" tabindex="-1">(2) 认同与恍然大悟 <a class="header-anchor" href="#_2-认同与恍然大悟" aria-label="Permalink to &quot;(2) 认同与恍然大悟&quot;">​</a></h3><p>前面说的内容成为 のです 句的理由。说话人用它来<strong>接受或确认</strong>结论，如“原来是这样”，常用来确认自己的猜测。</p><ul><li>由加さんは本当に漫画ファンなのですね。——原来由加你真的是漫画迷啊。</li></ul><h3 id="_3-为委婉的建议或请求铺垫背景" tabindex="-1">(3) 为委婉的建议或请求铺垫背景 <a class="header-anchor" href="#_3-为委婉的建议或请求铺垫背景" aria-label="Permalink to &quot;(3) 为委婉的建议或请求铺垫背景&quot;">​</a></h3><p><strong>～の（／ん）ですが、～</strong> 先摆出背景，说话人真正想要的内容与之相连。句子常常停在 <strong>が</strong>，由听话人推断出请求。</p><ul><li>新しいパソコンがほしいのですが。——我想要一台新电脑……（对店员说）</li><li>マックの最新モデルがいちばん軽いのですが。——Mac 的最新款是最轻的……（您考虑一下？）</li><li>あのう、テレビの音が大きいのですが。——那个，电视声音有点大……（能调小一点吗？）</li></ul><p><strong>注：</strong> 第一个例句是向店员说明需求的说法。第二个在说明事实的同时暗示“要不要考虑一下？”。第三个礼貌地描述情况，暗含请对方调小音量的请求。</p><h2 id="n-地点-へ-に-移动动词-移动的方向" tabindex="-1">N（地点）＋へ（／に）＋移动动词（移动的方向） <a class="header-anchor" href="#n-地点-へ-に-移动动词-移动的方向" aria-label="Permalink to &quot;N（地点）＋へ（／に）＋移动动词（移动的方向）&quot;">​</a></h2><p><strong>规则：</strong> 地点名词后的助词 <strong>へ</strong> 表示移动的<strong>方向</strong>。与 <strong>行く</strong>（去）、<strong>来る</strong>（来）、<strong>帰る</strong>（回）等移动动词搭配。这种用法中 <strong>へ</strong> 读作 <strong>e</strong>，不读 <em>he</em>。<strong>へ</strong> 也可以换成 <strong>に</strong>。</p><ul><li>毎朝、会社へ行きます。——我每天早上去公司。</li><li>いつ帰りますか。——你什么时候回去？</li><li>去年、家族と大阪に来ました。——去年我和家人来了大阪。</li></ul><h2 id="疑问词-も-全部否定" tabindex="-1">疑问词 ＋ も（全部否定） <a class="header-anchor" href="#疑问词-も-全部否定" aria-label="Permalink to &quot;疑问词 ＋ も（全部否定）&quot;">​</a></h2><p><strong>规则：</strong> <strong>疑问词 + も</strong> 与<strong>否定谓语</strong>连用表示全部否定：“谁也不／什么也不／哪个也不／哪儿也不”。誰も 意为谁也不，何も 什么也不，どれも 哪个也不，どこにも 哪儿也不。<strong>に</strong> 这类助词放在疑问词和 <strong>も</strong> 之间，如 どこ<strong>に</strong>も。</p><ul><li>夜中の博物館には誰もいません。——半夜的博物馆里一个人也没有。</li><li>引き出しには何もありません。——抽屉里什么也没有。</li><li>ここのカレー料理はどれもおいしくないです。——这里的咖喱菜哪个都不好吃。</li><li>この週末はどこにも行きません。——这个周末我哪儿也不去。</li></ul><h2 id="疑问词-か-不定-某" tabindex="-1">疑问词 ＋ か（不定：某……） <a class="header-anchor" href="#疑问词-か-不定-某" aria-label="Permalink to &quot;疑问词 ＋ か（不定：某……）&quot;">​</a></h2><p><strong>规则：</strong> <strong>疑问词 + か</strong> 表示<strong>不定</strong>：某人、某物、若干。誰か 意为某人，何人か 几个人，いくつか 几个，何回か 几次。它既可用于<strong>陈述句</strong>，也可用于疑问句。<strong>疑问词か</strong> 出现在疑问句中时，问句变成普通的<strong>是非问句</strong>，所以回答通常以 <strong>はい</strong> 或 <strong>いいえ</strong> 开头。比较：疑问词 + も + 否定，意为“谁也不／什么也不”。</p><ul><li>あのレストランにお客さんが何人かいます。——那家餐厅里有几位客人。</li><li>特に重要な理由がいくつかあります。——有几个特别重要的理由。</li><li>A：あのう、すみません。誰かいますか。——A：那个，打扰一下。有人在吗？</li><li>B：はい。——B：在。</li><li>以前、何回か来ました。——以前来过几次。</li></ul><h2 id="n-から-起点" tabindex="-1">N から（起点） <a class="header-anchor" href="#n-から-起点" aria-label="Permalink to &quot;N から（起点）&quot;">​</a></h2><p><strong>规则：</strong> 在表示<strong>时间</strong>、<strong>地点</strong>或<strong>顺序</strong>的名词后，助词 <strong>から</strong> 表示<strong>起点</strong>，相当于“从”。<strong>から</strong> 后面可以直接接 <strong>です</strong> 构成名词谓语句（“从 N 开始”）。表示起点的 <strong>から</strong> 也与表示终点的 <strong>まで</strong> 搭配：<strong>N₁ から N₂ まで</strong>，“从 N₁ 到 N₂”。</p><ul><li>体のトレーニングは明日からです。——体能训练从明天开始。</li><li>今から成績の発表です。——现在开始公布成绩。</li><li>ここからはテストの内容です。——从这里开始是考试内容。</li><li>会議は今月の4日から6日までです。——会议从本月 4 号开到 6 号。</li></ul><h2 id="n-じゃありませんか-惊讶的-这不是-吗" tabindex="-1">N じゃありませんか（惊讶的“这不是……吗”） <a class="header-anchor" href="#n-じゃありませんか-惊讶的-这不是-吗" aria-label="Permalink to &quot;N じゃありませんか（惊讶的“这不是……吗”）&quot;">​</a></h2><p><strong>规则：</strong> 这是名词句 <strong>N です</strong> 的<strong>反问</strong>形式，相当于“这不是 N 吗？”或“哎呀，这是 N 呀！”。它并不真的提问，而是带有<strong>惊讶或感叹</strong>，主要用于<strong>口语</strong>。</p><ul><li>とても有名な研究所じゃありませんか。——这不是非常有名的研究所嘛！</li><li>もう12時50分じゃありませんか。——这不已经 12 点 50 了嘛！</li><li>あ、あの人は、鈴木さんじゃありませんか。——啊，那个人不是铃木吗？</li></ul><h2 id="けど。-句末委婉的转折" tabindex="-1">…けど。（句末委婉的转折） <a class="header-anchor" href="#けど。-句末委婉的转折" aria-label="Permalink to &quot;…けど。（句末委婉的转折）&quot;">​</a></h2><p><strong>规则：</strong> 接续词 <strong>けど</strong> 是 <strong>けれども</strong> 的缩略，表示转折（“但是”）。这里它放在<strong>句末</strong>，表示<strong>委婉的转折</strong>：说话人话说一半，把后半句留着不说。这样语气<strong>柔和而含蓄</strong>，多用于口语。除了 <strong>けど</strong>，けれども 还可以缩略为 <strong>けれど</strong> 和 <strong>けども</strong>。</p><ul><li>これから会議なんですけど。——我们马上要开会了……（所以，如果您不介意的话）</li><li>そろそろお時間ですけれども。——时间差不多了……</li><li>A：中村さんはいますか。——A：中村在吗？</li><li>B：はい、私ですけど。——B：是的，我就是……（有什么事吗？）</li></ul><hr><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>动词部分开始（動詞）。</strong> 以上内容涵盖名词、形容词和助词。从这里开始讲动词。</p></div><h2 id="动词的活用分类-動詞の活用分類" tabindex="-1">动词的活用分类（動詞の活用分類） <a class="header-anchor" href="#动词的活用分类-動詞の活用分類" aria-label="Permalink to &quot;动词的活用分类（動詞の活用分類）&quot;">​</a></h2><p><strong>规则：</strong> 按<strong>活用类别</strong>给动词分类，是用好动词句的第一步。日本传统的学校语法与现在流行的教材对动词的分类略有不同，但多数只是<strong>名称</strong>不同。<strong>辞书形</strong>也叫<strong>基本形</strong>，是动词作为词典词条时不变形的形式。</p><table tabindex="0"><thead><tr><th>类别</th><th>日语名称</th><th>形式</th><th>例子</th></tr></thead><tbody><tr><td>I 类</td><td>五段動詞</td><td>辞书形以 <strong>う段假名</strong>结尾</td><td>休む、願う、わかる、ある</td></tr><tr><td>II 类</td><td>一段動詞</td><td>辞书形以 <strong>る</strong> 结尾，前面是 <strong>い段或え段假名</strong></td><td>寝る、起きる、忘れる</td></tr><tr><td>III 类</td><td>サ変動詞</td><td>单独的 <strong>する</strong>，或 <strong>汉语词 + する</strong></td><td>する、勉強する、運動する、運転する</td></tr><tr><td>III 类</td><td>カ変動詞</td><td>只有一个动词：<strong>来る</strong></td><td>来る</td></tr></tbody></table><h2 id="v-ます形-礼貌形与ます形词干" tabindex="-1">V ます形（礼貌形与ます形词干） <a class="header-anchor" href="#v-ます形-礼貌形与ます形词干" aria-label="Permalink to &quot;V ます形（礼貌形与ます形词干）&quot;">​</a></h2><p><strong>规则：</strong> 使用时，动词通常在辞书形的基础上接礼貌词尾 <strong>ます</strong>。在加 <strong>ます</strong> 之前，动词要按其<strong>活用类别</strong>变化（见上表）。这种变化叫做<strong>动词的活用（動詞の活用）</strong>。</p><h3 id="i-类-五段动词" tabindex="-1">I 类（五段动词） <a class="header-anchor" href="#i-类-五段动词" aria-label="Permalink to &quot;I 类（五段动词）&quot;">​</a></h3><p>把最后一个假名从 <strong>う段</strong>变为相应的 <strong>い段</strong>假名，再加 <strong>ます</strong>。</p><ul><li>休む：む → み + ます = 休みます</li><li>願う：う → い + ます = 願います</li><li>ある：る → り + ます = あります</li></ul><h3 id="ii-类-一段动词" tabindex="-1">II 类（一段动词） <a class="header-anchor" href="#ii-类-一段动词" aria-label="Permalink to &quot;II 类（一段动词）&quot;">​</a></h3><p>去掉最后的 <strong>る</strong>，再加 <strong>ます</strong>。</p><ul><li>起きる：去掉 る + ます = 起きます</li><li>寝る：去掉 る + ます = 寝ます</li><li>忘れる：去掉 る + ます = 忘れます</li></ul><h3 id="iii-类-サ变・カ变" tabindex="-1">III 类（サ变・カ变） <a class="header-anchor" href="#iii-类-サ变・カ变" aria-label="Permalink to &quot;III 类（サ变・カ变）&quot;">​</a></h3><ul><li><strong>サ变 する：</strong> する → し + ます = します；勉強する → 勉強し + ます = 勉強します</li><li><strong>カ变 来る：</strong> 来る（くる）→ 来（き）+ ます = 来ます（きます）</li></ul><h3 id="ます形词干" tabindex="-1">ます形词干 <a class="header-anchor" href="#ます形词干" aria-label="Permalink to &quot;ます形词干&quot;">​</a></h3><p>礼貌形去掉 <strong>ます</strong> 后剩下的部分就是 <strong>ます形词干</strong>，本笔记标为 <strong>V ます形</strong>。日本学校语法称之为 <strong>（第一）連用形</strong>。例如 ある 的礼貌形是 <strong>あります</strong>，所以它的ます形词干是 <strong>あり</strong>。</p><table tabindex="0"><thead><tr><th>类别</th><th>辞书形</th><th>礼貌形</th><th>ます形词干（連用形）</th></tr></thead><tbody><tr><td>I 类</td><td>わかる</td><td>わかります</td><td>わかり</td></tr><tr><td>II 类</td><td>忘れる</td><td>忘れます</td><td>忘れ</td></tr><tr><td>III 类</td><td>する</td><td>します</td><td>し</td></tr><tr><td>III 类</td><td>来る（くる）</td><td>来ます（きます）</td><td>来（き）</td></tr></tbody></table><h2 id="n-时间-に-时间点" tabindex="-1">N（时间）に（时间点） <a class="header-anchor" href="#n-时间-に-时间点" aria-label="Permalink to &quot;N（时间）に（时间点）&quot;">​</a></h2><p><strong>规则：</strong> 时间名词后的助词 <strong>に</strong> 表示动作发生的<strong>时间点</strong>，相当于“在……”。</p><ul><li>日曜日の午後1時半に会いましょうか。——我们星期天下午一点半见面好吗？</li><li>いつも夜9時に寝ます。——我总是晚上 9 点睡觉。</li><li>13日に中村さんの誕生日パーティーがあります。——13 号有中村的生日派对。</li></ul><h2 id="n-时间-ごろ-大约的时间" tabindex="-1">N（时间）＋ごろ（大约的时间） <a class="header-anchor" href="#n-时间-ごろ-大约的时间" aria-label="Permalink to &quot;N（时间）＋ごろ（大约的时间）&quot;">​</a></h2><p><strong>规则：</strong> 后缀 <strong>ごろ</strong>（也写作 <strong>頃</strong>）接在具体的时间名词后，意为那个时间的**“左右／前后”<strong>。用 <strong>ごろ</strong> 时，表示时间点的助词 <strong>に</strong> 可以</strong>省略**：2時ごろ帰ります 和 2時ごろに帰ります 都可以。</p><ul><li>いつも夜11時ごろ寝ます。——我总是晚上 11 点左右睡觉。</li><li>今日は2時ごろに帰ります。——今天我 2 点左右回去。</li><li>3月ごろ、桜が咲きます。——3 月前后樱花开放。</li><li>2000年ごろから、車が多くなりました。——从 2000 年前后开始，车越来越多了。</li></ul><h2 id="数量词-くらい-ぐらい-大约-左右" tabindex="-1">数量词＋くらい／ぐらい（大约，左右） <a class="header-anchor" href="#数量词-くらい-ぐらい-大约-左右" aria-label="Permalink to &quot;数量词＋くらい／ぐらい（大约，左右）&quot;">​</a></h2><p><strong>规则：</strong> <strong>くらい</strong>（也作 <strong>ぐらい</strong>）接在表示时间、金钱或数目的数量词后，意为**“大约／左右”**。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>与 <strong>ごろ</strong> 对比：ごろ 表示大约的<strong>时间点</strong>（2時ごろ，两点左右），くらい 表示大约的<strong>数量或时长</strong>（2時間ぐらい，大约两个小时）。</p></div><ul><li>発表は全部で2時間ぐらいでした。——发表一共大约两个小时。</li><li>食費は毎月3万円ぐらいです。——伙食费每月大约 3 万日元。</li><li>教室には学生が5人ぐらいいます。——教室里大约有 5 个学生。</li></ul><h2 id="なる-状态的变化" tabindex="-1">なる（状态的变化） <a class="header-anchor" href="#なる-状态的变化" aria-label="Permalink to &quot;なる（状态的变化）&quot;">​</a></h2><p><strong>规则：</strong> <strong>なる</strong>（“变成”）描述事物或其状态<strong>自然地发生变化</strong>。它可以与名词、形容词和动词结合；本课讲名词和形容词。</p><table tabindex="0"><thead><tr><th>词类</th><th>句型</th><th>例子</th></tr></thead><tbody><tr><td>名词</td><td><strong>N ＋ に ＋ なる</strong></td><td>会社員 → 会社員になる</td></tr><tr><td>い形容词</td><td><strong>去掉 い → く ＋ なる</strong></td><td>寒い → 寒くなる</td></tr><tr><td>な形容词</td><td><strong>A ＋ に ＋ なる</strong></td><td>静か → 静かになる</td></tr></tbody></table><ul><li>11月の初めから寒くなります。——从 11 月初开始变冷。</li><li>体調が大分よくなりました。——身体状况好多了。</li><li>日本語がかなり上手になりました。——日语变得相当好了。</li><li>今週末のイベントは中止になりました。——这个周末的活动取消了。</li><li>でも、午後から眠くなるから、何もできなくなります。——但是从下午开始就犯困，所以什么也做不了了。</li></ul><p><strong>注：</strong> 何もできなくなります 意为“（变得）什么也做不了”。できない 是 <strong>できる</strong>（会，能）的否定。否定的 ない 形后接 なる 时，<strong>ない 变为 なく</strong>：できない → <strong>できなくなる</strong>，即变得做不到。</p><h2 id="vましょう-vましょうか-邀请-我们-吧-好吗" tabindex="-1">Vましょう／Vましょうか（邀请：我们……吧／……好吗） <a class="header-anchor" href="#vましょう-vましょうか-邀请-我们-吧-好吗" aria-label="Permalink to &quot;Vましょう／Vましょうか（邀请：我们……吧／……好吗）&quot;">​</a></h2><p><strong>规则：</strong> <strong>ます形词干 ＋ ましょう</strong> 邀请听话人与你<strong>一起</strong>做某事，常与 <strong>いっしょに</strong> 连用：“我们……吧”。加疑问助词 <strong>か</strong>（<strong>Vましょうか</strong>）语气更<strong>委婉</strong>：是在询问对方是否同意。</p><ul><li>そろそろ帰りましょう。——我们差不多该回去了吧。</li><li>A：昼休みは、あそこの店へ行きましょうか。——A：午休时我们去那边那家店好吗？</li><li>B：そうしましょう。——B：好，就这么办。</li><li>A：今晩、家でゲームしましょうか。——A：今晚在我家打游戏好吗？</li><li>B：いいですね。——B：好啊。</li></ul><h2 id="ほうがいい-建议-比较好-接名词和形容词" tabindex="-1">～ほうがいい（建议：……比较好，接名词和形容词） <a class="header-anchor" href="#ほうがいい-建议-比较好-接名词和形容词" aria-label="Permalink to &quot;～ほうがいい（建议：……比较好，接名词和形容词）&quot;">​</a></h2><p><strong>规则：</strong> <strong>ほう</strong> 意为“一方／方向”。接上 <strong>ほうがいい</strong> 表示说话人对听话人的<strong>建议</strong>：“……比较好”。</p><table tabindex="0"><thead><tr><th>词类</th><th>句型</th><th>例子</th></tr></thead><tbody><tr><td>名词</td><td><strong>N ＋ の ＋ ほうがいい</strong></td><td>効率的なもの → 効率的なもののほうがいい</td></tr><tr><td>い形容词</td><td><strong>辞书形 ＋ ほうがいい</strong></td><td>近い → 近いほうがいい</td></tr><tr><td>な形容词</td><td><strong>A ＋ な ＋ ほうがいい</strong></td><td>安全 → 安全なほうがいい</td></tr></tbody></table><ul><li>もっと効率的なもののほうがいいですよ。——更有效率的东西比较好哦。</li><li>新しいアパートは会社に近いほうがいいです。——新公寓离公司近一点比较好。</li><li>毎日の食材は安全なほうがいいです。——每天的食材还是安全的好。</li></ul><h2 id="他动词与-を-标记直接宾语" tabindex="-1">他动词与 を（标记直接宾语） <a class="header-anchor" href="#他动词与-を-标记直接宾语" aria-label="Permalink to &quot;他动词与 を（标记直接宾语）&quot;">​</a></h2><p><strong>规则：</strong> 日语动词分为<strong>自动词</strong>和<strong>他动词</strong>。自动词不带直接宾语；他动词可以带。有些动词两种用法都有。用他动词时，在作直接宾语的名词后加 <strong>を</strong>。</p><ul><li>本を読みます。——我读书。</li><li>資料を調べます。——我查阅资料。</li></ul><p>直接宾语成为<strong>话题</strong>或表示<strong>也</strong>时，可以用 <strong>は</strong> 或 <strong>も</strong> 替换 <strong>を</strong>。</p><ul><li>メールはよく送りますが、手紙はあまり書きません。——邮件我常发，但信不太写。</li><li>休みの日は、よく映画を見ます。買い物もします。——休息日我常看电影。也去购物。</li></ul><h2 id="n-で-动作的场所-手段或工具" tabindex="-1">N で（动作的场所；手段或工具） <a class="header-anchor" href="#n-で-动作的场所-手段或工具" aria-label="Permalink to &quot;N で（动作的场所；手段或工具）&quot;">​</a></h2><h3 id="动作的场所" tabindex="-1">动作的场所 <a class="header-anchor" href="#动作的场所" aria-label="Permalink to &quot;动作的场所&quot;">​</a></h3><p><strong>规则：</strong> 在地点名词后加 <strong>で</strong>，表示<strong>动作发生的地点</strong>，相当于“在……”。</p><ul><li>伊藤先生のゼミでデータを集めました。——我在伊藤老师的研讨课上收集了数据。</li><li>私はよく喫茶店で小説を読みます。——我常在咖啡馆看小说。</li><li>日本では、口頭試験はどんな準備をしますか。——在日本，口试要做什么样的准备？</li></ul><h3 id="手段或工具" tabindex="-1">手段或工具 <a class="header-anchor" href="#手段或工具" aria-label="Permalink to &quot;手段或工具&quot;">​</a></h3><p><strong>规则：</strong> 在名词后加 <strong>で</strong>，表示<strong>做某个动作所用的工具或手段</strong>，相当于“用……／通过……”。</p><ul><li>スマホで外国語を勉強します。——我用智能手机学外语。</li><li>インターネットで資料を調べます。——我在网上查资料。</li><li>日本人はお箸で料理を食べます。——日本人用筷子吃饭。</li></ul><h2 id="n-に-动作的接受者或对象" tabindex="-1">N に（动作的接受者或对象） <a class="header-anchor" href="#n-に-动作的接受者或对象" aria-label="Permalink to &quot;N に（动作的接受者或对象）&quot;">​</a></h2><p><strong>规则：</strong> 在名词后加 <strong>に</strong>，表示<strong>动作所指向的人</strong>。根据动词不同，这个人可能是接受某物的人、见面的人或询问的人。</p><ul><li>中村さんにメールで資料を送ります。——我用邮件把资料发给中村。</li><li>午後、ジョージさんに会います。——下午我和乔治见面。</li><li>友達に簡単なやり方を聞きます。——我问朋友简单的做法。</li></ul><h2 id="n-なら-提出话题" tabindex="-1">N なら（提出话题） <a class="header-anchor" href="#n-なら-提出话题" aria-label="Permalink to &quot;N なら（提出话题）&quot;">​</a></h2><p><strong>规则：</strong> 在名词后加 <strong>なら</strong>，把这个名词提出来作为后面内容的<strong>话题</strong>。这个话题常常是已经提到过的，或听话人能从对话中推断出的事物。<strong>N なら、～</strong> 可以表示“说到 N，……”，或在回应对方的兴趣或请求时表示“如果是 N 的话，……”。</p><ul><li>日本語の小説なら、家には何冊かありますよ。——说到日语小说，我家里有几本哦。</li><li>A：新しいパソコンがほしいんですが。——我想要一台新电脑。</li><li>B：パソコンなら、こちらがいいですよ。——电脑的话，这台不错哦。</li><li>A：一緒に喫茶店に行きましょうか。——我们一起去咖啡馆好吗？</li><li>B：コーヒーなら、スタバのがいいですね。——要喝咖啡的话，星巴克的不错。</li></ul><h2 id="n-について-关于某个话题" tabindex="-1">N について（关于某个话题） <a class="header-anchor" href="#n-について-关于某个话题" aria-label="Permalink to &quot;N について（关于某个话题）&quot;">​</a></h2><p><strong>规则：</strong> 在名词后加 <strong>について</strong>，引出所讨论的主题：<strong>“关于 N”</strong>。后面可以接 <strong>です</strong> 构成谓语，也可以放在动词短语前，描述某人就该话题说、写或问的内容。</p><ul><li>経済のグローバリゼーションについてです。——是关于经济全球化的。</li><li>先週の旅行について作文を書きました。——我写了一篇关于上周旅行的作文。</li><li>今日の授業について、何か質問はありますか。——关于今天的课，有什么问题吗？</li></ul><h2 id="v-ます形词干-动作性名词-に-移动动词-移动的目的" tabindex="-1">V ます形词干／动作性名词 ＋ に ＋ 移动动词（移动的目的） <a class="header-anchor" href="#v-ます形词干-动作性名词-に-移动动词-移动的目的" aria-label="Permalink to &quot;V ます形词干／动作性名词 ＋ に ＋ 移动动词（移动的目的）&quot;">​</a></h2><p><strong>规则：</strong> 在动词的 <strong>ます形词干</strong>或表示活动的名词后加 <strong>に</strong>，再接 <strong>行く</strong>、<strong>来る</strong>、<strong>帰る</strong> 等移动动词。表示移动的<strong>目的</strong>：“去／来（某处）做……”。<strong>する</strong> 动词作动作性名词使用时，在 <strong>に</strong> 前只用其名词部分，不带 <strong>する</strong>。</p><ul><li>教室に忘れ物を取りに行きます。——我去教室拿忘了的东西。</li><li>サークルの仲間たちとお花見に行きます。——我和社团的伙伴们去赏花。</li><li>昨日中村さんのお家に遊びに行きました。——昨天我去中村家玩了。</li><li>散歩に出かけましょうか。——我们出去散步好吗？</li><li>資料を届けに来ました。——我是来送资料的。</li></ul><h2 id="v-ます形词干-ながら-同时做两件事" tabindex="-1">V ます形词干 ＋ ながら（同时做两件事） <a class="header-anchor" href="#v-ます形词干-ながら-同时做两件事" aria-label="Permalink to &quot;V ます形词干 ＋ ながら（同时做两件事）&quot;">​</a></h2><p><strong>规则：</strong> 在动词的 <strong>ます形词干</strong>后加 <strong>ながら</strong>，表示两个动作<strong>同时</strong>进行或交替持续，相当于“一边……一边……”。</p><ul><li>考えながら、パワーポイントを作ります。——我一边思考，一边做 PPT。</li><li>弟はいつも音楽を聴きながら、宿題をします。——弟弟总是一边听音乐一边写作业。</li><li>お茶をしながら、話しましょうか。——我们一边喝茶一边聊吧？</li></ul><h2 id="数量词-も-主观上数量多" tabindex="-1">数量词 ＋ も（主观上数量多） <a class="header-anchor" href="#数量词-も-主观上数量多" aria-label="Permalink to &quot;数量词 ＋ も（主观上数量多）&quot;">​</a></h2><p><strong>规则：</strong> 在数量词后加 <strong>も</strong>，表示说话人认为这个数量<strong>多或超出预期</strong>。数字本身不一定客观上很大：在某些语境下三个人就算多，<strong>３人も</strong> 可以表示“竟有三个人之多”。</p><ul><li>教室に学生が３人もいます。——教室里竟有三个学生。</li><li>議論は３日も続きました。——讨论整整持续了三天。</li><li>日系企業を５社も訪問しました。——我拜访了多达五家日资企业。</li></ul><p><strong>何度も：</strong> <strong>何度</strong>（“几次”）是疑问说法，但 <strong>何度も</strong> 意为**“很多次”**。具体次数不明确，说话人仍把它说成很多。</p><ul><li>あの映画は何度も見ましたよ。——那部电影我看了好多遍了。</li></ul><h2 id="でしょう-寻求确认-i" tabindex="-1">～でしょう（寻求确认 I） <a class="header-anchor" href="#でしょう-寻求确认-i" aria-label="Permalink to &quot;～でしょう（寻求确认 I）&quot;">​</a></h2><p><strong>规则：</strong> 在名词或形容词谓语后加 <strong>でしょう</strong>，用<strong>升调</strong>说出，表示寻求确认或反问：“……对吧？”“……不是吗？”。随意的口语中，<strong>でしょう</strong> 常缩略为 <strong>でしょ</strong>。</p><ul><li>李さんも留学生でしょ？——小李也是留学生，对吧？</li><li>勉強のほうが大事でしょう？——学习更重要，不是吗？</li><li>タバコを止めましょうよ。体に悪いでしょう？——戒烟吧。对身体不好，不是吗？</li></ul><h2 id="n-のための-n-目的-为了" tabindex="-1">N のための N（目的：为了） <a class="header-anchor" href="#n-のための-n-目的-为了" aria-label="Permalink to &quot;N のための N（目的：为了）&quot;">​</a></h2><p><strong>规则：</strong> <strong>ため</strong> 表示目的，常译为**“为了／供……用的”**。名词表示目的时，在其后加 <strong>の</strong>：<strong>N のため</strong>。如果后面还接名词，再加一个 <strong>の</strong> 连接：<strong>N₁ のための N₂</strong>，意为“供 N₁ 用的 N₂”。</p><ul><li>ここは小学生のための教室です。——这里是给小学生用的教室。</li><li>海外旅行のためのタオルを買いました。——我买了出国旅行用的毛巾。</li><li>期末試験のための勉強計画を考えます。——我来考虑期末考试的学习计划。</li></ul><h2 id="の-ん-です-说明-ii-动词" tabindex="-1">～の（／ん）です（说明 II：动词） <a class="header-anchor" href="#の-ん-です-说明-ii-动词" aria-label="Permalink to &quot;～の（／ん）です（说明 II：动词）&quot;">​</a></h2><p><strong>接续：</strong> 动词简体形 ＋ <strong>の（／ん）です</strong>。口语中多用 <strong>んです</strong>。</p><p><strong>规则：</strong> 这是上文名词和形容词部分介绍的说明句型 <strong>～の（／ん）です</strong> 的动词形式。用在疑问句中，是请听话人<strong>说明</strong>某事，常常是针对刚才说的话，或说话人注意到、推断出的情况。</p><ul><li>A：一緒に本屋へ行きませんか。——要不要一起去书店？</li><li>B：本屋へ何をしに行くんですか。——去书店做什么呢？</li><li>A：もう帰るんですか。——你已经要回去了吗？</li><li>B：ええ、もう時間なので。——是的，时间已经到了。</li><li>A：お腹が痛いんですか。——你肚子疼吗？</li><li>B：ええ、ちょっと。——嗯，有一点。</li></ul><h2 id="v-ませんか-委婉的邀请" tabindex="-1">V ませんか（委婉的邀请） <a class="header-anchor" href="#v-ませんか-委婉的邀请" aria-label="Permalink to &quot;V ませんか（委婉的邀请）&quot;">​</a></h2><p><strong>规则：</strong> 用礼貌的否定疑问 <strong>V ませんか</strong> 邀请对方<strong>一起</strong>做某事。语气比 <strong>V ましょうか</strong> 更委婉，可以与 <strong>いっしょに</strong>（“一起”）连用。相当于“要不要……？”“我们……好吗？”。</p><ul><li>来週のサークル活動にいっしょに参加しませんか。——要不要和我一起参加下周的社团活动？</li><li>明日、映画を見に行きませんか。——明天要不要去看电影？</li><li>ここで写真を撮りませんか。——我们在这里拍张照好吗？</li></ul><h2 id="动词的简体形式-動詞の簡体形式" tabindex="-1">动词的简体形式（動詞の簡体形式） <a class="header-anchor" href="#动词的简体形式-動詞の簡体形式" aria-label="Permalink to &quot;动词的简体形式（動詞の簡体形式）&quot;">​</a></h2><p><strong>规则：</strong> 与名词和形容词谓语一样，动词谓语也有**礼貌（敬体）<strong>和</strong>简体（简体）**两种形式。下表比较了时态和肯否的四种组合。<strong>Vる</strong> 表示动词的辞书形；并非所有辞书形动词都以 <strong>る</strong> 结尾。简体的否定形和过去形在后面的语法部分详细讲解。</p><table tabindex="0"><thead><tr><th>时态</th><th>肯否</th><th>礼貌形</th><th>简体形</th></tr></thead><tbody><tr><td>非过去（现在／将来）</td><td>肯定</td><td>V ます</td><td>V る（辞书形）</td></tr><tr><td>非过去（现在／将来）</td><td>否定</td><td>V ません</td><td>V ない</td></tr><tr><td>过去</td><td>肯定</td><td>V ました</td><td>V た</td></tr><tr><td>过去</td><td>否定</td><td>V ませんでした</td><td>V なかった</td></tr></tbody></table><p><strong>用法：</strong> 礼貌形常用于正式场合和客气的对话。简体形更亲近，常用于朋友和家人之间。书面语中，简体使陈述语气直接，常见于论文和新闻报道。</p><h2 id="v-る-辞书形" tabindex="-1">V る（辞书形） <a class="header-anchor" href="#v-る-辞书形" aria-label="Permalink to &quot;V る（辞书形）&quot;">​</a></h2><p><strong>规则：</strong> <strong>辞书形</strong>是动词的基本形式，即词典中词条所用的形式。它也是<strong>简体非过去肯定</strong>形。有时也叫<strong>基本形</strong>或<strong>原形</strong>。下面的对照显示了它与礼貌的 <strong>ます</strong> 形的比较。</p><table tabindex="0"><thead><tr><th>文体</th><th>例句</th><th>中文</th></tr></thead><tbody><tr><td>礼貌</td><td>スマホでウェブサイトを閲覧します。</td><td>我用智能手机浏览网站。</td></tr><tr><td>简体</td><td>スマホでウェブサイトを閲覧する。</td><td>我用智能手机浏览网站。</td></tr><tr><td>礼貌</td><td>よく徹夜します。</td><td>我经常熬通宵。</td></tr><tr><td>简体</td><td>よく徹夜する。</td><td>我经常熬通宵。</td></tr></tbody></table><h2 id="v-ない-简体否定形" tabindex="-1">V ない（简体否定形） <a class="header-anchor" href="#v-ない-简体否定形" aria-label="Permalink to &quot;V ない（简体否定形）&quot;">​</a></h2><p><strong>规则：</strong> 在动词的否定词干后加否定辅助形容词 <strong>ない</strong>，构成<strong>简体非过去否定</strong>形。词干的构成取决于动词类别。</p><h3 id="i-类-五段动词-1" tabindex="-1">I 类（五段动词） <a class="header-anchor" href="#i-类-五段动词-1" aria-label="Permalink to &quot;I 类（五段动词）&quot;">​</a></h3><p>把最后一个假名从 <strong>う段</strong>变为相应的 <strong>あ段</strong>假名，再加 <strong>ない</strong>。以 <strong>う</strong> 结尾的动词，在 <strong>ない</strong> 前把 <strong>う</strong> 变为 <strong>わ</strong>。</p><table tabindex="0"><thead><tr><th>辞书形</th><th>变化</th><th>简体否定</th></tr></thead><tbody><tr><td>使う</td><td>う → わ</td><td>使わない</td></tr><tr><td>歩く</td><td>く → か</td><td>歩かない</td></tr><tr><td>帰る</td><td>る → ら</td><td>帰らない</td></tr></tbody></table><h3 id="ii-类-一段动词-1" tabindex="-1">II 类（一段动词） <a class="header-anchor" href="#ii-类-一段动词-1" aria-label="Permalink to &quot;II 类（一段动词）&quot;">​</a></h3><p>去掉最后的 <strong>る</strong>，再加 <strong>ない</strong>。</p><table tabindex="0"><thead><tr><th>辞书形</th><th>简体否定</th></tr></thead><tbody><tr><td>見る</td><td>見ない</td></tr><tr><td>食べる</td><td>食べない</td></tr><tr><td>集める</td><td>集めない</td></tr></tbody></table><h3 id="iii-类-サ变・カ变-1" tabindex="-1">III 类（サ变・カ变） <a class="header-anchor" href="#iii-类-サ变・カ变-1" aria-label="Permalink to &quot;III 类（サ变・カ变）&quot;">​</a></h3><ul><li><strong>する：</strong> する → しない；利用する → 利用しない。</li><li><strong>来る（くる）：</strong> 来る → 来ない（こない）。</li></ul><p><strong>例外：</strong> <strong>ある</strong> 的简体否定是 <strong>ない</strong>，不是 <em>あらない</em>。</p><ul><li>この週末は家に帰らない。——这个周末我不回家。</li><li>今の学生はあまり運動しない。——现在的学生不太运动。</li></ul><h3 id="简体过去否定-v-なかった" tabindex="-1">简体过去否定：V なかった <a class="header-anchor" href="#简体过去否定-v-なかった" aria-label="Permalink to &quot;简体过去否定：V なかった&quot;">​</a></h3><p>构成简体过去否定时，把 <strong>V ない</strong> 最后的 <strong>い</strong> 变为 <strong>かった</strong>：<strong>V ない → V なかった</strong>。对应礼貌形 <strong>V ませんでした</strong>。</p><ul><li>宿題が多くて、昨夜、あまり寝なかった。——作业很多，昨晚没怎么睡。</li><li>A：昨日のビールは？——昨天的啤酒呢？</li><li>B：冷蔵庫だよ。——在冰箱里啊。</li><li>A：ビールは冷蔵庫になかったよ。——冰箱里没有啤酒啊。</li></ul><h2 id="动词连体形-動詞連体形" tabindex="-1">动词连体形（動詞連体形） <a class="header-anchor" href="#动词连体形-動詞連体形" aria-label="Permalink to &quot;动词连体形（動詞連体形）&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p><strong>规则：</strong> 动词可以<strong>直接放在名词前</strong>描述或限定该名词。这叫做动词的<strong>连体形</strong>。它的形式与动词的简体形相同；根据意思选择合适的时态和肯否。例如 <strong>行く場所</strong> 意为“（某人）要去的地方”，<strong>飛ばない可能性</strong> 意为“（某物）不飞的可能性”。</p></div><ul><li>授業の予習や復習、課題をやる時間。——预习、复习功课和做作业的时间。</li><li>明日行く場所はどこですか。——你明天要去的地方是哪里？</li><li>雨なので、飛行機が飛ばない可能性があります。——因为下雨，飞机有可能不起飞。</li></ul><h2 id="n1-期间-に-n2-数量-v-频率" tabindex="-1">N₁（期间）に N₂（数量）V（频率） <a class="header-anchor" href="#n1-期间-に-n2-数量-v-频率" aria-label="Permalink to &quot;N₁（期间）に N₂（数量）V（频率）&quot;">​</a></h2><p><strong>规则：</strong> 在表示<strong>期间</strong>（常为一段时间）的名词后加 <strong>に</strong>，再给出<strong>次数</strong>，表示在这段期间内动作发生的频率。相当于“每……几次”。</p><ul><li>週に３回運動する。——我每周运动三次。</li><li>２か月に１回ぐらい映画を観る。——我大约每两个月看一次电影。</li><li>１年に１回中国へ帰る。——我每年回一次中国。</li></ul><h2 id="n1-についての-n2-关于-n1-的-n2" tabindex="-1">N₁ についての N₂（关于 N₁ 的 N₂） <a class="header-anchor" href="#n1-についての-n2-关于-n1-的-n2" aria-label="Permalink to &quot;N₁ についての N₂（关于 N₁ 的 N₂）&quot;">​</a></h2><p><strong>规则：</strong> <strong>N について</strong> 意为“关于 N”，用来引出话题。当这个短语修饰后面的名词时加 <strong>の</strong>：<strong>N₁ についての N₂</strong>，意为“关于 N₁ 的 N₂”。</p><ul><li>こちらは大学生のライフスタイルについてのアンケートです。——这是关于大学生生活方式的问卷。</li><li>このウェブサイトには、来週の口頭試験についての情報はない。——这个网站上没有关于下周口试的信息。</li><li>来週は期末試験なので、明日から経済学についての本を読む。——下周就期末考试了，所以我明天开始读关于经济学的书。</li></ul><h2 id="ほとんど-あまり-否定动词-几乎不-不太" tabindex="-1">ほとんど／あまり ＋ 否定动词（几乎不／不太） <a class="header-anchor" href="#ほとんど-あまり-否定动词-几乎不-不太" aria-label="Permalink to &quot;ほとんど／あまり ＋ 否定动词（几乎不／不太）&quot;">​</a></h2><p><strong>规则：</strong> 副词 <strong>ほとんど</strong> 与否定动词连用，意为**“几乎不”<strong>。<strong>あまり</strong> 也与否定动词搭配，意为</strong>“不太常”<strong>或</strong>“不怎么”**。<strong>ほとんど</strong> 的否定程度一般比 <strong>あまり</strong> 更强。</p><ul><li>インターネットやSNSはほとんど利用しません。——我几乎不用网络和社交媒体。</li><li>漫画はときどき読みますが、アニメはほとんど見ません。——漫画我有时看，但动画几乎不看。</li><li>Eメールはあまり使いません。——我不太用电子邮件。</li><li>梅雨の季節はあまり晴れません。——梅雨季节不怎么放晴。</li></ul><h2 id="n-助词-の-n-修饰名词" tabindex="-1">N ＋ 助词 ＋ の ＋ N（修饰名词） <a class="header-anchor" href="#n-助词-の-n-修饰名词" aria-label="Permalink to &quot;N ＋ 助词 ＋ の ＋ N（修饰名词）&quot;">​</a></h2><p><strong>规则：</strong> 除了像 <strong>私の車</strong>（“我的车”）那样直接连接两个名词外，<strong>の</strong> 还可以接在 <strong>N と</strong>、<strong>N から</strong>、<strong>N で</strong>、<strong>N へ</strong> 等有实际意义的助词短语后。这样构成的短语修饰后面的名词。</p><table tabindex="0"><thead><tr><th>动作短语</th><th>名词短语</th><th>中文</th></tr></thead><tbody><tr><td>友達と食事する</td><td>友達との食事</td><td>和朋友的聚餐</td></tr><tr><td>明日からゴールデンウィークが始まる</td><td>明日からのゴールデンウィーク</td><td>从明天开始的黄金周</td></tr><tr><td>デパートで買い物する</td><td>デパートでの買い物</td><td>在百货商店的购物</td></tr><tr><td>大学の授業などに出席する</td><td>大学の授業などへの出席</td><td>出席大学的课程等活动</td></tr></tbody></table><p><strong>注：</strong> 没有 <strong>N にの N</strong> 这种形式。短语表示<strong>朝向／到</strong>某个目的地或方向时，改用 <strong>N への N</strong>。</p><ul><li>雨の影響で、外国からの観光客が減少しました。——受降雨影响，来自国外的游客减少了。</li><li>後輩との食事会はとても楽しかったです。——和学弟学妹们的聚餐非常开心。</li><li>台風の影響で、香港へのフライトはキャンセルになりました。——受台风影响，飞往香港的航班取消了。</li></ul><h2 id="n1-や-n2-など-列举例子" tabindex="-1">N₁ や N₂ など（列举例子） <a class="header-anchor" href="#n1-や-n2-など-列举例子" aria-label="Permalink to &quot;N₁ や N₂ など（列举例子）&quot;">​</a></h2><p><strong>规则：</strong> 用 <strong>や</strong> 列举两个或以上的<strong>例子</strong>，而不是列出一组中的全部。<strong>など</strong> 意为“等等”。两者可以一起用作 <strong>N₁ や N₂ など</strong>，<strong>など</strong> 也可以单独接在名词后。</p><ul><li>インターネットやSNSなど——网络、社交媒体等等。</li><li>A：デパートに何がありますか。——百货商店里有什么？</li><li>B：映画館や本屋などがあります。——有电影院、书店等等。</li><li>A：いつもどこで服を買いますか。——你平时在哪里买衣服？</li><li>B：ユニクロやタオバオで買います。——在优衣库、淘宝这些地方买。</li></ul>',334)])])}const b=r(l,[["render",g]]);export{p as __pageData,b as default};
